"""Flat, traceable event normalization."""
import json

def _pack(value): return json.dumps(value, ensure_ascii=False, sort_keys=True) if value is not None else None

def normalize_event(event, *, chunk_id, source_file, line_number):
    c=event.get('context') or {}; a=c.get('active_app') or {}; b=c.get('active_browser_tab') or {}; r=event.get('correlation') or {}; p=event.get('payload') or {}; n=p.get('new_app') or {}; q=p.get('previous_app') or {}; f=p.get('file_reference') or {}; e=p.get('element') or {}
    return {'event_id':event.get('event_id'),'session_id':event.get('session_id'),'chunk_id':r.get('chunk_id') or chunk_id,'timestamp_ms':event.get('timestamp_ms'),'timestamp_iso':event.get('timestamp_iso'),'layer':event.get('layer'),'event_type':event.get('event_type'),'active_app':a.get('app_name'),'process_name':a.get('process_name'),'window_title':a.get('window_title'),'active_app_process_id':a.get('process_id'),'browser_title':b.get('title'),'browser_url':b.get('url'),'browser_tab_id':b.get('tab_id'),'sequence_number':r.get('sequence_number'),'ms_since_last_event':r.get('ms_since_last_event'),'triggered_by':r.get('triggered_by'),'correlated_events_json':_pack(r.get('correlated_events')),'new_app':n.get('app_name'),'previous_app':q.get('app_name'),'key':p.get('key'),'character':p.get('character'),'modifiers_json':_pack(p.get('modifiers')),'target_field_json':_pack(p.get('target_field')),'click_coordinates_json':_pack(p.get('click_coordinates') or p.get('coordinates')),'browser_element_json':_pack(e),'browser_element_attributes_json':_pack(e.get('attributes')),'browser_field_json':_pack(p.get('field')),'clipboard_text':p.get('text_content'),'clipboard_length':p.get('text_length'),'screenshot_filename':f.get('filename'),'screenshot_relative_path':f.get('relative_path'),'extracted_text':(c.get('extracted_text') or {}).get('text'),'extracted_text_source':(c.get('extracted_text') or {}).get('source'),'visible_windows_json':_pack(c.get('visible_windows')),'open_apps_json':_pack(c.get('open_apps')),'extensions_json':_pack(event.get('extensions')),'raw_line_number':line_number,'source_file':source_file}
